using System;
using System.Collections.Generic;

// PROGRAM: Implementasi Breadth-First Search (BFS) Sederhana
public class SimpleGraph
{
    private readonly Dictionary<string, List<string>> _adj = new();

    public void AddEdge(string u, string v)
    {
        if (!_adj.ContainsKey(u)) _adj[u] = new List<string>();
        _adj[u].Add(v);
    }

    public List<string> TraverseBfs(string startNode)
    {
        var visited = new HashSet<string>();
        var queue = new Queue<string>();
        var result = new List<string>();

        visited.Add(startNode);
        queue.Enqueue(startNode);

        while (queue.Count > 0)
        {
            string current = queue.Dequeue();
            result.Add(current);

            if (_adj.TryGetValue(current, out var neighbors))
            {
                foreach (var neighbor in neighbors)
                {
                    if (visited.Add(neighbor)) // Jika belum pernah dikunjungi
                    {
                        queue.Enqueue(neighbor);
                    }
                }
            }
        }

        return result;
    }
}

public class Program
{
    public static void Main()
    {
        var g = new SimpleGraph();
        g.AddEdge("API Gateway", "Auth Service");
        g.AddEdge("API Gateway", "Order Service");
        g.AddEdge("Order Service", "Payment Service");
        g.AddEdge("Order Service", "Inventory Service");

        var traversal = g.TraverseBfs("API Gateway");
        Console.WriteLine("Urutan Penelusuran Layanan (BFS):");
        Console.WriteLine(string.Join(" -> ", traversal));
    }
}

