using System;
using System.Collections.Generic;
using System.Linq;

public class DependencyCycleDetector
{
    public static bool HasCircularDependency(string[] dependencies)
    {
        if (dependencies == null || dependencies.Length == 0) return false;

        var adj = new Dictionary<string, List<string>>();
        var inDegree = new Dictionary<string, int>();
        var allNodes = new HashSet<string>();

        foreach (var dep in dependencies)
        {
            if (string.IsNullOrWhiteSpace(dep)) continue;
            var parts = dep.Split("->", StringSplitOptions.RemoveEmptyEntries);
            if (parts.Length != 2) continue;

            string u = parts[0].Trim();
            string v = parts[1].Trim();

            allNodes.Add(u);
            allNodes.Add(v);

            if (!adj.ContainsKey(u)) adj[u] = new List<string>();
            adj[u].Add(v);

            inDegree[v] = inDegree.GetValueOrDefault(v, 0) + 1;
            if (!inDegree.ContainsKey(u)) inDegree[u] = 0;
        }

        if (allNodes.Count == 0) return false;

        var queue = new Queue<string>();
        foreach (var node in allNodes)
        {
            if (inDegree.GetValueOrDefault(node, 0) == 0)
            {
                queue.Enqueue(node);
            }
        }

        int processedCount = 0;
        while (queue.Count > 0)
        {
            string curr = queue.Dequeue();
            processedCount++;

            if (adj.TryGetValue(curr, out var neighbors))
            {
                foreach (var next in neighbors)
                {
                    inDegree[next]--;
                    if (inDegree[next] == 0)
                    {
                        queue.Enqueue(next);
                    }
                }
            }
        }

        return processedCount < allNodes.Count;
    }

    public static void Main()
    {
        string[] safeDeps = { "App->Core", "Core->Data" };
        Console.WriteLine($"Siklus (Aman): {HasCircularDependency(safeDeps)}");

        string[] cycleDeps = { "A->B", "B->C", "C->A" };
        Console.WriteLine($"Siklus (Bahaya): {HasCircularDependency(cycleDeps)}");
    }
}
